fwEvents.on("fw-builder:form-builder:register-items",function(i){fwFormBuilderSimpleItem(i,"amount",{required:!0,preview:function(e){var n=String(e&&e.suggested||"").split(",").map(function(r){return r.trim()}).filter(Boolean).slice(0,5);return n.map(function(r){return'<span style="display:inline-block;border:1px solid #c3c4c7;border-radius:4px;padding:2px 10px;margin:0 4px 4px 0">'+r.replace(/[<>&"]/g,"")+"</span>"}).join("")+(e&&e.allow_other!=="no"?'<span style="display:inline-block;border:1px dashed #c3c4c7;border-radius:4px;padding:2px 10px">Other</span>':"")}})});
